-- Complete authoritative application database. Apply once through the Supabase SQL editor.
-- This private schema is NOT exposed through PostgREST; browsers use the Python API.
BEGIN;
CREATE SCHEMA IF NOT EXISTS app_private;
REVOKE ALL ON SCHEMA app_private FROM PUBLIC, anon, authenticated;
SET LOCAL search_path=app_private,pg_catalog;
CREATE TABLE IF NOT EXISTS users (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "email" TEXT,
  "password_hash" TEXT,
  "created_at" TEXT,
  "plan" TEXT DEFAULT 'free',
  "name" TEXT DEFAULT '',
  "supabase_uid" TEXT DEFAULT '',
  "billing_start" TEXT DEFAULT '',
  "billing_end" TEXT DEFAULT '',
  "email_verified" BIGINT DEFAULT 0,
  "trial_started_at" TEXT DEFAULT '',
  "deleted_at" TEXT DEFAULT '',
  PRIMARY KEY("id"),
  UNIQUE(email)
);
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON users FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS workspaces (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT DEFAULT 1,
  "name" TEXT,
  "pitch" TEXT,
  "signals" TEXT,
  "rules" TEXT,
  "blocklist" TEXT DEFAULT '',
  "profile" JSONB DEFAULT '{}'::jsonb NOT NULL,
  "pilot_feedback" JSONB DEFAULT '{}'::jsonb,
  PRIMARY KEY("id")
);
ALTER TABLE workspaces ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON workspaces FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS leads (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "workspace_id" BIGINT,
  "comment_id" TEXT,
  "video_id" TEXT,
  "video_title" TEXT,
  "author" TEXT,
  "text" TEXT,
  "score" BIGINT DEFAULT 0,
  "reason" TEXT DEFAULT '',
  "reply" TEXT DEFAULT '',
  "status" TEXT DEFAULT 'new',
  "feedback" TEXT DEFAULT '',
  "channel_title" TEXT DEFAULT '',
  "channel_id" TEXT DEFAULT '',
  "unlocked" BIGINT DEFAULT 0,
  "published_at" TEXT DEFAULT '',
  "source_updated_at" TEXT DEFAULT '',
  "buyer_type" TEXT DEFAULT 'unknown',
  "evidence" JSONB DEFAULT '{}'::jsonb,
  "analysis_revision" TEXT DEFAULT '',
  "analysis_state" TEXT DEFAULT 'legacy',
  "outcome" TEXT DEFAULT 'new',
  "revenue_minor" BIGINT DEFAULT 0,
  "currency" TEXT DEFAULT '',
  "rejection_reason" TEXT DEFAULT '',
  "outcome_updated_at" TEXT DEFAULT '',
  "retrieved_at" TEXT DEFAULT '',
  "retention_expired" BIGINT DEFAULT 0,
  PRIMARY KEY("id"),
  UNIQUE(workspace_id,comment_id)
);
ALTER TABLE leads ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON leads FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS jobs (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "workspace_id" BIGINT,
  "user_id" BIGINT DEFAULT 1,
  "type" TEXT,
  "status" TEXT DEFAULT 'running',
  "msg" TEXT DEFAULT '',
  "progress" BIGINT DEFAULT 0,
  "result" TEXT DEFAULT '',
  "error" TEXT DEFAULT '',
  "created_at" TEXT,
  "updated_at" TEXT,
  "payload" TEXT DEFAULT '',
  "started_at" TEXT DEFAULT '',
  "execution_error" TEXT DEFAULT '',
  PRIMARY KEY("id")
);
ALTER TABLE jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON jobs FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS upgrade_interest (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT,
  "plan" TEXT,
  "created_at" TEXT,
  PRIMARY KEY("id")
);
ALTER TABLE upgrade_interest ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON upgrade_interest FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS runs (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "workspace_id" BIGINT,
  "user_id" BIGINT DEFAULT 1,
  "units_used" BIGINT DEFAULT 0,
  "new_leads_count" BIGINT DEFAULT 0,
  "status" TEXT DEFAULT 'completed',
  "details" TEXT DEFAULT '',
  "created_at" TEXT,
  "search_calls" BIGINT DEFAULT 0,
  PRIMARY KEY("id")
);
ALTER TABLE runs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON runs FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS email_logs (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT DEFAULT 1,
  "to_email" TEXT,
  "subject" TEXT,
  "body" TEXT,
  "email_type" TEXT DEFAULT 'lead_alert',
  "provider" TEXT DEFAULT 'supabase',
  "status" TEXT DEFAULT 'sent',
  "created_at" TEXT,
  PRIMARY KEY("id")
);
ALTER TABLE email_logs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON email_logs FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS api_usage (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "run_id" BIGINT,
  "user_id" BIGINT,
  "workspace_id" BIGINT,
  "provider" TEXT NOT NULL,
  "operation" TEXT NOT NULL,
  "bucket" TEXT NOT NULL,
  "units" BIGINT DEFAULT 0 NOT NULL,
  "input_tokens" BIGINT DEFAULT 0,
  "output_tokens" BIGINT DEFAULT 0,
  "cost_usd" DOUBLE PRECISION,
  "status" TEXT DEFAULT 'started',
  "created_at" TEXT NOT NULL,
  "funding" TEXT DEFAULT 'legacy',
  PRIMARY KEY("id")
);
ALTER TABLE api_usage ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON api_usage FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS integration_state (
  "provider" TEXT,
  "status" TEXT NOT NULL,
  "checked_at" TEXT NOT NULL,
  PRIMARY KEY("provider")
);
ALTER TABLE integration_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON integration_state FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS lead_outcome_events (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "lead_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "previous_outcome" TEXT,
  "outcome" TEXT NOT NULL,
  "revenue_minor" BIGINT DEFAULT 0,
  "currency" TEXT DEFAULT '',
  "rejection_reason" TEXT DEFAULT '',
  "created_at" TEXT NOT NULL,
  PRIMARY KEY("id")
);
ALTER TABLE lead_outcome_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON lead_outcome_events FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS match_grants (
  "user_id" BIGINT,
  "lead_id" BIGINT,
  "period_key" TEXT,
  "created_at" TEXT,
  PRIMARY KEY("user_id","lead_id")
);
ALTER TABLE match_grants ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON match_grants FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS analysis_credits (
  "id" TEXT,
  "user_id" BIGINT,
  "period_key" TEXT,
  "amount" BIGINT,
  "status" TEXT,
  "created_at" TEXT,
  PRIMARY KEY("id")
);
ALTER TABLE analysis_credits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON analysis_credits FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS request_limits (
  "scope" TEXT,
  "identity" TEXT,
  "window" BIGINT,
  "count" BIGINT,
  PRIMARY KEY("scope","identity","window")
);
ALTER TABLE request_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON request_limits FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS trial_claims (
  "identity" TEXT,
  "user_id" BIGINT,
  "kind" TEXT,
  "created_at" TEXT,
  PRIMARY KEY("identity")
);
ALTER TABLE trial_claims ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON trial_claims FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS policy_acceptance (
  "user_id" BIGINT,
  "version" TEXT,
  "accepted_at" TEXT,
  PRIMARY KEY("user_id","version")
);
ALTER TABLE policy_acceptance ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON policy_acceptance FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS billing_subscriptions (
  "id" TEXT,
  "user_id" BIGINT,
  "plan" TEXT,
  "status" TEXT,
  "created_at" TEXT,
  PRIMARY KEY("id")
);
ALTER TABLE billing_subscriptions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON billing_subscriptions FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS billing_events (
  "id" TEXT,
  "payload_hash" TEXT,
  "created_at" TEXT,
  PRIMARY KEY("id")
);
ALTER TABLE billing_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON billing_events FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS deletion_requests (
  "user_id" BIGINT,
  "requested_at" TEXT,
  "status" TEXT,
  "error" TEXT DEFAULT '',
  PRIMARY KEY("user_id")
);
ALTER TABLE deletion_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON deletion_requests FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS lifecycle_sync (
  "lead_id" BIGINT,
  "updated_at" TEXT,
  "error" TEXT DEFAULT '',
  PRIMARY KEY("lead_id")
);
ALTER TABLE lifecycle_sync ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON lifecycle_sync FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS lifecycle_cleanup_tasks (
  "task" TEXT,
  "updated_at" TEXT,
  "error" TEXT DEFAULT '',
  PRIMARY KEY("task")
);
ALTER TABLE lifecycle_cleanup_tasks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON lifecycle_cleanup_tasks FROM PUBLIC,anon,authenticated;
CREATE UNIQUE INDEX IF NOT EXISTS users_auth_identity ON users(supabase_uid) WHERE COALESCE(supabase_uid,'')!='';
CREATE INDEX IF NOT EXISTS workspaces_owner ON workspaces(user_id);
CREATE INDEX IF NOT EXISTS leads_workspace_score ON leads(workspace_id,score DESC);
CREATE INDEX IF NOT EXISTS leads_refresh_date ON leads(retrieved_at) WHERE retention_expired=0;
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status,created_at);
CREATE INDEX IF NOT EXISTS jobs_owner ON jobs(user_id,created_at);
CREATE INDEX IF NOT EXISTS api_usage_bucket_date ON api_usage(bucket,created_at);
CREATE INDEX IF NOT EXISTS api_usage_owner ON api_usage(user_id,created_at);
CREATE INDEX IF NOT EXISTS api_usage_run ON api_usage(run_id);
CREATE INDEX IF NOT EXISTS match_grants_period ON match_grants(user_id,period_key);
CREATE INDEX IF NOT EXISTS analysis_credits_period ON analysis_credits(user_id,period_key,status);
CREATE UNIQUE INDEX IF NOT EXISTS billing_one_open_subscription ON billing_subscriptions(user_id) WHERE status IN ('creating','created','authenticated','active','pending');
CREATE TABLE IF NOT EXISTS schema_version(id INTEGER PRIMARY KEY,version INTEGER NOT NULL);
ALTER TABLE schema_version ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON schema_version FROM PUBLIC,anon,authenticated;
INSERT INTO schema_version VALUES(1,1) ON CONFLICT(id) DO NOTHING;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA app_private FROM PUBLIC,anon,authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA app_private REVOKE ALL ON TABLES FROM PUBLIC,anon,authenticated;
COMMIT;
